/* istanbul ignore file */

import { faker } from '@faker-js/faker';
import React from 'react';
import { Column } from 'react-table';

export const generatePersonMock = (
  dataQuantity: number
): { name: string; age: number; address: string }[] => {
  const mockResult: { name: string; age: number; address: string }[] = [];

  for (let i = 0; i < dataQuantity; i += 1) {
    mockResult.push({
      name: faker.name.findName(),
      address: faker.address.streetAddress(),
      age: faker.datatype.number(100),
    });
  }
  return mockResult;
};

export const personColumnsMock = [
  {
    Header: 'Name',
    accessor: 'name',
    style: {
      width: '40%',
    },
    disableSortBy: true,
  },
  {
    Header: 'Age',
    accessor: 'age',
    style: {
      width: '20%',
    },
    disableSortBy: true,
  },
  {
    Header: 'Address',
    accessor: 'address',
    style: {
      width: '40%',
    },
    disableSortBy: true,
  },
];

export const generateColumns = ({
  sortable,
  render,
}: {
  sortable?: boolean;
  render?: (value: unknown, row: Record<string, unknown>) => React.ReactNode;
}): Column[] => [
  {
    Header: 'Name',
    accessor: 'name',
    style: {
      width: '40%',
    },
    ...(!sortable && { disableSortBy: true }),
    ...(render && { customRender: render }),
  },
  {
    Header: 'Age',
    accessor: 'age',
    style: {
      width: '20%',
    },
    ...(!sortable && { disableSortBy: true }),
  },
  {
    Header: 'Address',
    accessor: 'address',
    style: {
      width: '40%',
    },
    ...(!sortable && { disableSortBy: true }),
  },
];
